CREATE TABLE mission_runs(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),agent TEXT NOT NULL,mission TEXT NOT NULL,state TEXT NOT NULL,execution_engine TEXT NOT NULL,manifest TEXT NOT NULL,created_at TEXT NOT NULL,finished_at TEXT);
CREATE TABLE agent_messages(id TEXT PRIMARY KEY,sender TEXT NOT NULL,receiver TEXT NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL,source_task TEXT,recipient_task TEXT,status TEXT NOT NULL,created_at TEXT NOT NULL,acknowledged_at TEXT);
CREATE TABLE conversations(id TEXT PRIMARY KEY,lead_id TEXT NOT NULL,contact TEXT NOT NULL,is_group INTEGER NOT NULL DEFAULT 0,human_takeover INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 0,processed_revision INTEGER NOT NULL DEFAULT 0,due_at REAL,last_inbound REAL,status TEXT NOT NULL DEFAULT 'IDLE');
CREATE TABLE inbound_messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),body TEXT NOT NULL,received_at REAL NOT NULL,revision INTEGER NOT NULL);
CREATE TABLE reply_outbox(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL,revision INTEGER NOT NULL,idempotency_key TEXT NOT NULL UNIQUE,body TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,sent_at TEXT,UNIQUE(conversation_id,revision));
